import{_ as a,o,c as e,ai as s}from"./chunks/framework.BBSijY9B.js";const m=JSON.parse('{"title":"云电脑怎么用","description":"理解 Bot 的云端电脑：它能做什么、文件放哪、怎么旁观和接管、卡住了怎么办。","frontmatter":{"related":["/basics/files-reports","/basics/safety-approvals","/faq/faq"],"title":"云电脑怎么用","description":"理解 Bot 的云端电脑：它能做什么、文件放哪、怎么旁观和接管、卡住了怎么办。","section":"basics","order":1,"tags":["基础","云电脑","浏览器","文件"],"sources":["https://docs.x.ai/grok-bot/computer-and-apps","https://cursor.com/docs/grok-bot/work"],"wordCount":757,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"云电脑怎么用 | WANGXXXL"}],["meta",{"property":"og:description","content":"理解 Bot 的云端电脑：它能做什么、文件放哪、怎么旁观和接管、卡住了怎么办。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/cloud-computer"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-cloud-computer-87207fcb46.png"}],["meta",{"property":"og:image:alt","content":"云电脑怎么用 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"云电脑怎么用 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"理解 Bot 的云端电脑：它能做什么、文件放哪、怎么旁观和接管、卡住了怎么办。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-cloud-computer-87207fcb46.png"}],["meta",{"name":"twitter:image:alt","content":"云电脑怎么用 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/cloud-computer"}]]},"headers":[],"relativePath":"basics/cloud-computer.md","filePath":"basics/cloud-computer.md","lastUpdated":1792485206000}'),i={name:"basics/cloud-computer.md"};function c(l,t,r,n,p,d){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="云电脑怎么用" tabindex="-1">云电脑怎么用 <a class="header-anchor" href="#云电脑怎么用" aria-label="Permalink to &quot;云电脑怎么用&quot;">​</a></h1><p>Grok Bot 和普通聊天 AI 最大的区别，就是它有一台<strong>持续存在的云端电脑</strong>：一台 Linux 机器，带浏览器、桌面、终端和文件系统。Bot 在上面打开网页、下载文件、跑脚本、生成表格。你合上笔记本，它照样在干活。</p><h2 id="先记住三件事" tabindex="-1">先记住三件事 <a class="header-anchor" href="#先记住三件事" aria-label="Permalink to &quot;先记住三件事&quot;">​</a></h2><ol><li><strong>一个账号一台电脑</strong>。你名下所有 Bot 共用这台电脑，文件、浏览器登录状态、命令行凭证都是共享的。好处是 A Bot 存的文件 B Bot 能接着用；代价是它们之间没有权限隔离。</li><li><strong>每个 Bot 有自己的屏幕</strong>。多个 Bot 可以同时用浏览器，互不抢屏幕，但一个 Bot 同一时间只做一项&quot;操作电脑&quot;的任务。</li><li><strong>它和你面前的电脑是两回事</strong>。云电脑上的文件，你本地看不到；你本地的文件，它默认也碰不到（除非你单独授权，见<a href="/basics/local-computer">在自己电脑上干活</a>）。</li></ol><h2 id="旁观它在做什么" tabindex="-1">旁观它在做什么 <a class="header-anchor" href="#旁观它在做什么" aria-label="Permalink to &quot;旁观它在做什么&quot;">​</a></h2><p>在对话右侧点电脑预览，就能看到它的屏幕：点了哪里、输入了什么、打开了哪个页面。你可以随时离开，关掉预览不影响工作。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你现在打开的是哪个网页？为什么停在这一步？截一张图给我看。</span></span></code></pre></div><h2 id="需要你亲自来的时候-接管" tabindex="-1">需要你亲自来的时候：接管 <a class="header-anchor" href="#需要你亲自来的时候-接管" aria-label="Permalink to &quot;需要你亲自来的时候：接管&quot;">​</a></h2><p>遇到密码、验证码、扫码登录、人机验证、付款确认这类步骤，Bot 会把控制权交给你：</p><ol><li>在对话里的请求上选择接管（或打开电脑画面选择接管控制）。</li><li>只完成那一步，比如登录。</li><li>选择完成，然后告诉 Bot 继续。</li></ol><p>登录状态会保留在云电脑上，下次（以及你的其他 Bot）可以直接用。</p><div class="warning custom-block"><p class="custom-block-title">不要在聊天里发密码</p><p>密码、验证码永远不要直接打在对话里。需要输入时用接管，或用应用弹出的安全表单——那里输入的内容会被遮挡，不进入聊天记录。</p></div><h2 id="文件放在哪" tabindex="-1">文件放在哪 <a class="header-anchor" href="#文件放在哪" aria-label="Permalink to &quot;文件放在哪&quot;">​</a></h2><p>云电脑上有一个共享工作目录 <code>/workspace</code>。重要的成果建议让 Bot 按项目建文件夹存放：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以后这个项目的所有文件都放在 /workspace/季度复盘/ 下面，按日期命名。</span></span></code></pre></div><p>临时目录、手动装的软件属于&quot;可替换&quot;的东西，系统更新或恢复后可能需要重装；文件和登录状态通常会保留。</p><h2 id="卡住了怎么办" tabindex="-1">卡住了怎么办 <a class="header-anchor" href="#卡住了怎么办" aria-label="Permalink to &quot;卡住了怎么办&quot;">​</a></h2><p>按&quot;从轻到重&quot;的顺序来：</p><ol><li>在出错的地方点重试，或重新打开对话。</li><li>重启 Grok Bot 应用，检查有没有更新。</li><li>如果界面提示可以恢复云电脑，就用恢复。</li><li>在设置的电脑相关页面里更新云电脑。</li><li>最后才考虑重置云电脑。</li></ol><div class="tip custom-block"><p class="custom-block-title">对话不会丢</p><p>对话记录存在云电脑之外，即使重置电脑也不会丢。但重置前没来得及保存的最新改动可能找不回来，重要文件记得随时发到对话里或存进 <code>/workspace</code>。</p></div><p>具体按钮名称可能随版本变化，以官方最新说明为准。</p>',21)])])}const h=a(i,[["render",c]]);export{m as __pageData,h as default};
